#!/usr/bin/env python3
"""Construye informe HTML autónomo y visores locales de fuentes, sin dependencias."""
import html,json
from pathlib import Path
from urllib.parse import quote
R=Path(__file__).resolve().parents[1];E=R/'evidencias'
def esc(x):return html.escape(str(x),quote=True)
def load(p):return json.loads((E/p).read_text())
def num(x):return f'{x:,}'.replace(',','.')
def source_link(s):
 path=s['path'];url='evidencias/fuentes-html/'+quote(path+'.html')+f"#L{s['start']}"
 return f'<a class="cite" href="{url}">{esc(Path(path).stem)} · L{s["start"]}–{s["end"]} · {esc(s.get("section",""))}</a>'
def sources(obj):return '<div class="sources">'+''.join(source_link(s) for s in obj.get('sources',[]) if isinstance(s,dict) and all(k in s for k in ['path','start','end']))+'</div>'
def value(x):
 if isinstance(x,str):return '<p>'+esc(x)+'</p>'
 if isinstance(x,list):return '<ul>'+''.join('<li>'+value(v)+'</li>' for v in x)+'</ul>'
 if isinstance(x,dict):return '<dl>'+''.join('<dt>'+esc(k)+'</dt><dd>'+value(v)+'</dd>' for k,v in x.items())+'</dl>'
 return esc(x)
def items(data):
 out=''
 for x in data:
  if isinstance(x,dict):
   title=x.get('title',x.get('id',x.get('text','Entrada')))
   if len(title)>145:title=title[:142]+'…'
   body={k:v for k,v in x.items() if k not in ('sources','title','id')}
   out+=f'<details><summary><b>{esc(x.get("id",""))}</b> {esc(title)}</summary>{value(body)}{sources(x)}</details>'
  else:out+=value(x)
 return out

def main():
 m=load('medicion.json');v=load('validacion-evidencias.json');compare=load('comparacion-manual.json');inv=load('inventario.json');arms={a:load(a+'/resultado.json') for a in ['baseline','scripts']}
 # Visor verificable con anclas de línea; originales sólo leídos.
 for f in inv['files']:
  if not f['included']:continue
  path=f['path'];text=(E/'fuentes'/path).read_text();dest=E/'fuentes-html'/(path+'.html');dest.parent.mkdir(parents=True,exist_ok=True)
  lines=''.join(f'<div id="L{i}"><a href="#L{i}">{i:04}</a> {esc(l)}</div>' for i,l in enumerate(text.splitlines(),1))
  dest.write_text('<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>'+esc(path)+'</title><style>body{background:#111827;color:#e2e8f0;font:14px ui-monospace,monospace;padding:24px}div{white-space:pre-wrap;overflow-wrap:anywhere;padding:2px}a{color:#7dd3fc}div:target{background:#334155}h1{font:22px system-ui}p{overflow-wrap:anywhere}</style><h1>'+esc(path)+'</h1><p>SHA256 '+f['sha256']+'</p>'+lines+'</html>')
 a=m['arms']['baseline'];b=m['arms']['scripts'];reduction=m['comparison']['constructed_prompt_tokens']['reduction_percent']
 style='''
:root{--ink:#172638;--muted:#52657a;--paper:#f4f6f8;--line:#dae2e9;--accent:#086b6d;--purple:#6b4cad;--gold:#f5d68c}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:80px}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.65 system-ui,-apple-system,sans-serif}a{color:#075d7c;text-underline-offset:3px}nav{position:sticky;top:0;z-index:2;background:#fff;border-bottom:1px solid var(--line);padding:13px 28px;display:flex;gap:22px;flex-wrap:wrap;font-size:13px}nav a{text-decoration:none;font-weight:650}.wrap{max-width:1180px;margin:auto;padding:0 30px}header{background:#102b3b;color:#f0f6fa;padding:64px 0 50px}header p{max-width:850px;color:#c4d6df;font-size:19px}.eyebrow{font-size:12px;letter-spacing:2px;font-weight:750;color:#f5d68c;text-transform:uppercase}h1{font-size:clamp(32px,5vw,60px);line-height:1.1;letter-spacing:-2px;margin:18px 0}h2{font-size:29px;letter-spacing:-.6px;margin:0 0 18px}h3{font-size:19px;margin-top:26px}section{margin:36px 0;background:white;border:1px solid var(--line);border-radius:16px;padding:32px}p{margin:10px 0 17px}.lead{font-size:21px;max-width:930px}.pill{display:inline-block;padding:5px 11px;background:#214454;color:#ebf4f8;border-radius:20px;font-size:12px;margin-right:8px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:15px;margin-top:24px}.kpi{padding:24px;border-radius:12px;background:#173c4d}.kpi strong{display:block;font-size:35px;color:white;letter-spacing:-1px}.kpi span{font-size:13px;color:#c6dbe4}.callout{background:#fff6df;border-left:4px solid #bd8412;padding:17px 22px;margin:22px 0}.good{background:#e7f3f0;border-color:#17816f}.two{display:grid;grid-template-columns:1fr 1fr;gap:24px}.step{border-top:3px solid var(--accent);padding-top:15px}.muted,small{color:var(--muted)}table{width:100%;border-collapse:collapse;font-size:14px;margin:20px 0}th{text-align:left;background:#eef3f6}td,th{padding:12px 13px;border-bottom:1px solid var(--line);vertical-align:top}td:first-child{font-weight:650}pre{background:#132d3c;color:#edf6fa;border-radius:10px;padding:20px;overflow:auto;font:13px/1.65 ui-monospace,monospace}code{font:13px ui-monospace,monospace}details{border:1px solid var(--line);border-radius:9px;padding:13px 17px;margin:9px 0}summary{cursor:pointer;font-size:14px}summary b{color:var(--accent);margin-right:7px}details p,details li{font-size:14px}details dl{font-size:14px}dt{font-weight:700;color:var(--muted);margin-top:11px}dd{margin-left:12px}dd p{margin:5px 0}.sources{display:flex;gap:7px;flex-wrap:wrap;margin:12px 0}.cite{background:#edf4f7;border-radius:5px;font-size:11px;padding:4px 8px;overflow-wrap:anywhere}.barrow{display:grid;grid-template-columns:135px 1fr 85px;gap:14px;align-items:center;margin:15px 0;font-size:14px}.track{height:30px;background:#edf1f4;border-radius:5px;overflow:hidden}.fill{height:100%;background:var(--purple)}.fill.b{background:var(--accent)}.scroll{overflow-x:auto}ul{padding-left:23px}li{margin:6px 0}.badge{font-size:12px;background:#edf3f5;padding:4px 9px;border-radius:5px}.casegroup{margin:18px 0}.controls{display:flex;gap:8px;margin:16px 0}button{border:1px solid var(--line);border-radius:7px;background:#f3f7f9;padding:9px 14px;cursor:pointer;color:var(--ink)}footer{padding:12px 0 60px;color:var(--muted);font-size:13px}.hash{overflow-wrap:anywhere;font:11px ui-monospace,monospace}.tight{font-size:14px}@media(max-width:760px){.grid,.two{grid-template-columns:1fr}.wrap{padding:0 16px}section{padding:22px}nav{gap:13px;padding:12px 16px}.barrow{grid-template-columns:85px 1fr 65px}header{padding:40px 0}h1{letter-spacing:-1px}}@media print{nav,.controls{display:none}section{break-inside:avoid}details{break-inside:avoid}body{background:white}header{color:#102b3b;background:white}header p{color:#52657a}.kpi{background:#eef3f6}.kpi strong,.kpi span{color:#172638}}
'''
 body=f'''<!doctype html><html lang="es-AR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Post Harness · Ensayo documental de QA agentizada</title><style>{style}</style></head><body>
<nav aria-label="Secciones"><a href="#conclusion">Hallazgo</a><a href="#metodo">Método</a><a href="#medicion">Medición</a><a href="#calidad">Cobertura</a><a href="#entregas">Propuestas y casos</a><a href="#uso">Uso</a><a href="#evidencias">Evidencias</a></nav>
<header><div class="wrap"><div class="eyebrow">Experimento local · QA agentizada · 27 octubre 2026</div><h1>Menos contexto.<br>Evidencia que se puede seguir.</h1><p>Un ensayo con el segundo cerebro de OWUI: lectura completa frente a navegación Python, con dos evaluadores en contextos separados y una misma feature simulada.</p><span class="pill">Sin modificar OWUI</span><span class="pill">Sin MCP ni otro harness</span><span class="pill">Conteo observable ≠ usage real</span><div class="grid"><div class="kpi"><strong>80</strong><span>documentos leídos e indexados</span></div><div class="kpi"><strong>{num(a['constructed_prompt_tokens'])} → {num(b['constructed_prompt_tokens'])}</strong><span>tokens en prompts reconstruidos</span></div><div class="kpi"><strong>{reduction:.1f}%</strong><span>reducción en ese paquete de entrada</span></div></div></div></header>
<main class="wrap"><section id="conclusion"><div class="eyebrow" style="color:var(--accent)">Decisión respaldada por este ensayo</div><h2>{esc(compare['headline'])}</h2><p class="lead">{esc(compare['conclusion'])}</p><div class="callout"><b>Alcance de la cifra.</b> El {reduction:.1f}% usa como denominador {num(a['constructed_prompt_tokens'])} tokens del prompt baseline reconstruido. No mide consumo real de inferencia, facturación, razonamiento interno ni ahorro universal. Tampoco demuestra equivalencia de calidad con un solo par de ejecuciones.</div><p>{esc(compare['recommendation'])}</p></section>
<section id="corpus"><h2>Corpus y feature elegida</h2><div class="two"><div><h3>Una fuente existente, preservada</h3><p>80 Markdown, {num(m['corpus']['bytes'])} bytes, {num(m['corpus']['raw_tokens_sum_per_file'])} tokens sumados por archivo. Se excluyeron dos <code>.DS_Store</code> por ser metadatos binarios. No había otros documentos textuales ni AGENTS.md aplicables.</p><p>Las notas tienen frontmatter, encabezados, MOCs, enlaces y un índice maestro. El índice declara 79 notas a 08/07/2026; el inventario actual contiene 80 Markdown al incluir el propio índice. Home declara v1.3.0: es una versión documentada, sin verificar contra la aplicación.</p><p class="hash">Revisión snapshot: {m['corpus']['snapshot_revision']}</p></div><div><h3>Renovar acceso temporal a un File</h3><p>Una acción desde el chat para volver a obtener acceso de lectura. Obliga a combinar ACL, JWT, objeto S3 o descarga local, expiración, errores, carreras de UI e i18n.</p><p>El mock propone TTL entero 60–3600 s (default 3600), validación 422, bloqueo de pending y ninguna mutación de contenido/ACL. Estas reglas propuestas no son funcionalidad existente validada.</p><p>La decisión sobre <code>last_accessed_at</code> queda abierta: renovar un enlace puede afectar la política de limpieza si se interpreta como acceso.</p></div></div><details><summary>Requisitos y consigna completos, idénticos para ambos</summary><pre>{esc((E/'consigna-comun.md').read_text())}</pre></details><p class="tight">Los hechos de OWUI son afirmaciones del segundo cerebro. No se inspeccionó código real ni se verificaron versiones, CVEs o controles de seguridad contra la aplicación. Las contradicciones documentales se conservan como dudas.</p></section>
<section id="metodo"><h2>Cómo se controló la comparación</h2><div class="two"><div class="step"><b>A · Lectura completa</b><p>Evaluador con <code>fork_turns=none</code>, 80 documentos en 16 lotes de cinco. Lectura completa antes de proponer. Cada lote registra texto con líneas y SHA256. No usa el recuperador.</p></div><div class="step"><b>B · Sólo scripts</b><p>Otro evaluador con contexto limpio y la misma configuración heredada, requisitos y consigna. Ejecuta cinco consultas prefijadas, luego amplía por necesidad. No accede a fuentes directamente ni a las respuestas baseline.</p></div></div><p>Ambos se despacharon en paralelo tras congelar scripts e instrucciones. La actualización del usuario autorizó ese paralelismo y reemplazó el orden secuencial original. Cada entrega se congeló con hashes antes de la comparación. El coordinador había leído el corpus para definir el mock; esa selección y la revisión manual pueden tener sesgo. Los evaluadores no heredaron esa conversación ni vieron las respuestas del otro.</p><p>Calibración separada: routing <code>urlIdx</code> y CSP dev/OpenShift. No se ajustaron pesos usando los casos de evaluación. El índice sólo contiene documentos del corpus; ningún caso baseline ni respuesta generada entra en la recuperación.</p><div class="callout good"><b>Aislamiento de contexto, no un ensayo estadístico.</b> Son dos ejecuciones reales de agentes con contexto inicial separado; no son dos fases de una conversación compartida. La configuración de modelo se heredó sin override. La herramienta no expone identificador de backend, semilla, temperatura ni contadores usage; no se puede certificar igualdad de esos parámetros internos.</div><p><a href="evidencias/01-protocolo.md">Protocolo y enmienda</a> · <a href="evidencias/pre-evaluacion-congelado.json">Entradas congeladas</a> · <a href="evidencias/despachos.json">Mensajes de despacho</a></p></section>
<section id="medicion"><h2>Tokens: lo medido y lo que falta</h2><p>Tokenizer identificado: <code>{m['tokenizer']['package']} {m['tokenizer']['version']} / {m['tokenizer']['encoding']}</code>. Es un proxy reproducible; no se afirma que coincida con el tokenizer del modelo ejecutor.</p><div class="barrow"><b>Completo</b><div class="track"><div class="fill" style="width:100%"></div></div><span>{num(a['constructed_prompt_tokens'])}</span></div><div class="barrow"><b>Scripts</b><div class="track"><div class="fill b" style="width:{100*b['constructed_prompt_tokens']/max(1,a['constructed_prompt_tokens']):.2f}%"></div></div><span>{num(b['constructed_prompt_tokens'])}</span></div>
<div class="scroll"><table><thead><tr><th>Contenido contado una vez</th><th>A · Completo</th><th>B · Scripts</th><th>Interpretación</th></tr></thead><tbody>'''
 rows=[('Instrucciones observables', 'instructions_tokens_sum','Consigna + modalidad + despacho; B incluye las consultas prefijadas.'),('Resultados de lectura/herramientas','tool_results_tokens_sum','Texto efectivamente presentado según archivos stdout registrados; incluye JSON, rutas y repeticiones.'),('Invocaciones serializadas, proxy','serialized_invocations_proxy_tokens_sum','argv y metadatos del log; no equivale al JSON real de la llamada de herramienta.'),('Artefactos de salida generados','generated_artifact_tokens_sum','resultado.json + comportamiento.md; excluye pensamiento, comentarios, tool-call de escritura y mensaje final.'),('Suma de artefactos, proxy','observed_artifact_sum_proxy','Suma de las cuatro filas anteriores; no es total de tokens facturados.'),('Prompt reconstruido exacto','constructed_prompt_tokens','Instrucciones y resultados concatenados con separadores publicados; excluye invocaciones y salidas generadas.')]
 for label,key,detail in rows:body+=f'<tr><td>{label}</td><td>{num(a[key])}</td><td>{num(b[key])}</td><td>{detail}</td></tr>'
 body+=f'''<tr><td>Usage real / total acumulado de rondas</td><td>No disponible</td><td>No disponible</td><td>No se dispone de transcript interno, reenvíos acumulados, caché, razonamiento o contexto oculto.</td></tr></tbody></table></div><p>Corpus crudo concatenado: {num(m['corpus']['raw_tokens_concatenated'])} tokens; corpus numerado reconstruido: {num(m['corpus']['annotated_context_tokens'])}. Son denominadores distintos. La reducción de resultados de herramientas es {m['comparison']['tool_results_tokens_sum']['reduction_percent']:.1f}% sobre {num(a['tool_results_tokens_sum'])}; la reducción de la suma proxy de artefactos es {m['comparison']['observed_artifact_sum_proxy']['reduction_percent']:.1f}% sobre {num(a['observed_artifact_sum_proxy'])}. No mezclar esos porcentajes.</p><h3>Preparación, consulta y reutilización</h3><p>La indexación procesó localmente los 170.573 bytes y produjo {num(m['preparation']['index_bytes'])} bytes de SQLite, sin llamadas LLM. La calibración presentó {num(m['preparation']['calibration_result_tokens_sum'])} tokens de resultados al coordinador; se contabiliza por separado. El coordinador además leyó todo el corpus para diseñar este ensayo: no hay usage real de esa preparación. No se amortiza ese trabajo humano/LLM como si fuera gratis.</p><p>Para N tareas de este mismo tamaño, el paquete construido sería N × {num(a['constructed_prompt_tokens'])} frente a N × {num(b['constructed_prompt_tokens'])}, más preparación y nuevas ampliaciones. Es un escenario aritmético con este denominador, no una predicción de inferencia. En una sesión con caché, instrucciones ya presentes o consultas más amplias, el resultado puede cambiar.</p><p>Rondas locales registradas: A {a['calls']}, B {b['calls']}. Tiempo dentro de los scripts: A {a['local_tool_seconds_sum']:.3f} s; B {b['local_tool_seconds_sum']:.3f} s, excluyendo inicio del intérprete y generación del modelo. No se midió latencia de inferencia ni costo monetario. Más llamadas puede compensar parte del ahorro de contexto.</p><p><a href="evidencias/medicion.json">Conteos, hashes y huella del tokenizer</a> · <a href="evidencias/prompt-construido-baseline.txt">Prompt A reconstruido</a> · <a href="evidencias/prompt-construido-scripts.txt">Prompt B reconstruido</a></p></section>
<section id="calidad"><h2>Cobertura documental y calidad revisada</h2><p>Los números de casos se informan para ubicar las entregas, sin usarlos como puntaje: A {len(arms['baseline']['cases'])}; B {len(arms['scripts']['cases'])}. La revisión es manual, por el coordinador y sin ciego. No hay pruebas de aplicación ejecutadas ni oráculos verificados contra código.</p><div class="scroll"><table><thead><tr><th>Criterio previo</th><th>A · Completo</th><th>B · Scripts</th><th>Juicio y límite</th></tr></thead><tbody>'''
 for row in compare['criteria']:body+='<tr>'+''.join('<td>'+esc(row[k])+'</td>' for k in ['criterion','baseline','scripts','assessment'])+'</tr>'
 body+='</tbody></table></div><h3>Diferencias en las propuestas</h3>'+value(compare['implementation_comparison'])+'<h3>Omisiones, dudas y duplicación</h3>'+value(compare['limitations'])
 body+='<h3>Fidelidad y trazabilidad automáticas</h3><div class="scroll"><table><thead><tr><th>Comprobación</th><th>A</th><th>B</th></tr></thead><tbody>'
 for label,key in [('Documentos presentados','documents_presented'),('Líneas fuente únicas presentadas','unique_source_lines_presented'),('Referencias con rango inválido','invalid_citations'),('Referencias no enteramente presentadas','citations_not_fully_presented'),('Duplicados exactos de precondición/pasos/esperado','exact_duplicate_cases')]:body+=f'<tr><td>{label}</td><td>{num(v["arms"]["baseline"][key])}</td><td>{num(v["arms"]["scripts"][key])}</td></tr>'
 body+='</tbody></table></div><p>El validador comprueba rangos, exposición material y extractos literales. Que una cita exista y haya sido presentada no prueba que respalde semánticamente el esperado. La revisión manual conserva las salvedades de permisos, concurrencia y efectos que siguen sin contrato.</p><p><a href="evidencias/validacion-evidencias.json">Validación de citas e integridad</a> · <a href="evidencias/comparacion-manual.json">Comparación con IDs de casos</a></p></section>'
 body+='<section id="entregas"><h2>Propuestas y casos completos</h2><p>Cada entrega conserva su contenido original congelado. Abrí los casos para ver precondiciones, pasos, esperado, origen del oráculo y enlaces a líneas fuente.</p><div class="controls"><button type="button" onclick="document.querySelectorAll(\'#entregas details\').forEach(e=>e.open=true)">Expandir entregas</button><button type="button" onclick="document.querySelectorAll(\'#entregas details\').forEach(e=>e.open=false)">Contraer entregas</button></div>'
 for arm,label in [('baseline','A · Lectura completa'),('scripts','B · Navegación Python')]:
  data=arms[arm];body+=f'<div class="casegroup"><h3>{label}</h3><p><a href="evidencias/{arm}/resultado.json">Resultado original JSON</a> · <a href="evidencias/{arm}/comportamiento.md">Bitácora del evaluador</a> · <a href="evidencias/{arm}/congelado.json">Hashes congelados</a></p>'
  for key,title in [('facts','Hechos y clasificación'),('implementation','Propuesta de implementación'),('cases','Casos documentales'),('questions','Preguntas abiertas'),('conflicts','Conflictos detectados'),('omissions','Omisiones reconocidas')]:body+=f'<details><summary>{title} ({len(data.get(key,[]))})</summary>'+items(data.get(key,[]))+'</details>'
  body+='</div>'
 body+='</section>'
 body+='''<section id="tecnica"><h2>Por qué estos scripts</h2><p>El corpus ya tiene notas cortas, metadatos y enlaces. SQLite permite persistencia transaccional y actualización por hash; Python estándar calcula ranking léxico BM25 sobre fragmentos, refuerza rutas/títulos/metadatos y ofrece diversidad por documento. No hace falta un modelo para resumir, un servicio vectorial ni una ontología de OWUI.</p><div class="two"><div><h3>Qué devuelve</h3><ul><li>Extractos literales con archivo, sección, líneas y SHA256.</li><li>Frontmatter crudo: estados, aliases, versiones o advertencias tal como estén escritos.</li><li>Enlaces con ambigüedades y faltantes visibles; ampliación por líneas o relaciones.</li><li>Paginación y truncamientos explícitos; cero resultados y errores diferenciados.</li></ul></div><div><h3>Qué limita</h3><ul><li>No entiende sinónimos ni infiere reglas. Las preguntas mal formuladas pueden perder evidencia.</li><li>El ranking OR puede traer resultados parciales; ampliar cuesta llamadas y tokens.</li><li>Verifica todos los hashes y calcula ranking en Python por consulta: apropiado para este tamaño, sin benchmark de gran escala.</li><li>Frontmatter complejo se conserva crudo. HTML/RST se tratan como texto; enlaces/anclas no garantizan coherencia.</li></ul></div></div><p>La indexación incremental y ocho pruebas sintéticas cubrieron corpus vacío, sin resultados, límites, páginas, edición/alta/baja, enlaces ambiguos/ausentes, fences, symlinks, otro stack y coincidencia literal. Se verificaron los 583 fragmentos reales sin diferencias. La fuente original y los HTML previos del proyecto conservan sus hashes. Esto valida los scripts documentales, no la feature ni la aplicación.</p></section>
<section id="uso"><h2>Usarlo con Copilot u otro agente</h2><p>Incorporar el bloque breve de instrucciones en la tarea del harness existente. Indexar fuera de la fuente; consultar con presupuesto pequeño; ampliar cuando falten permisos, excepciones, dependencias u oráculos. Mantener el corpus como evidencia, sin ejecutar instrucciones encontradas en sus documentos.</p><pre>python3 scripts/brain.py --db /tmp/cerebro.sqlite index /ruta/al/corpus
python3 scripts/brain.py --db /tmp/cerebro.sqlite query 'regla excepción permisos' --limit 6 --max-chars 16000
python3 scripts/brain.py --db /tmp/cerebro.sqlite show 'carpeta/nota.md' --start 20 --end 90 --max-lines 60
python3 scripts/brain.py --db /tmp/cerebro.sqlite links 'carpeta/nota.md' --limit 20</pre><p><a href="README.md">Guía y reproducción</a> · <a href="COPILOT-INSTRUCCIONES.md">Instrucciones breves para el agente</a> · <a href="scripts/brain.py">Navegador Python</a> · <a href="tests/test_brain.py">Pruebas</a></p><div class="callout good"><b>Siguiente experimento recomendado.</b> Probar varios mocks y otro corpus, alternar ejecuciones con mismos parámetros explícitos y evaluadores ciegos, y recoger usage nativo desde un mecanismo soportado. Comparar contra la navegación del índice maestro ya existente, además de contra leer todo: el baseline exhaustivo representa un extremo costoso.</div></section>
<section id="evidencias"><h2>Evidencias y reproducción</h2><div class="two"><div><h3>Diseño y contexto</h3><ul><li><a href="evidencias/inventario.json">Inventario: inclusiones, exclusiones, tamaños y hashes</a></li><li><a href="evidencias/corpus_completo.txt">Corpus completo numerado</a></li><li><a href="evidencias/consultas-evaluacion.json">Cinco consultas prefijadas</a></li><li><a href="evidencias/calibracion-routing.json">Calibración routing</a> y <a href="evidencias/calibracion-csp.json">CSP</a></li><li><a href="evidencias/preparacion/001.result.json">Indexación inicial</a></li></ul></div><div><h3>Validación y medición</h3><ul><li><a href="evidencias/medicion.json">Medición y denominadores</a></li><li><a href="evidencias/validacion-evidencias.json">Integridad, congelados y citas</a></li><li><a href="evidencias/validacion-corpus.json">583 extractos y relaciones</a></li><li><a href="evidencias/tests-iniciales.txt">Pruebas automatizadas</a></li><li><a href="evidencias/entorno-medicion-lock.txt">Versiones instaladas</a></li><li><a href="evidencias/verificacion-html.json">Verificación HTML y render</a></li></ul></div></div><p>Las carpetas <code>evidencias/baseline/lecturas</code> y <code>evidencias/scripts/lecturas</code> contienen cada invocación y stdout exacto. El reporte no requiere Internet, librerías CDN ni servicios externos. Las fuentes tienen visores locales con anclas por línea.</p></section></main><footer class="wrap">Post Harness · Ensayo documental local · 27/10/2026 (America/Argentina/Buenos_Aires). Sin despliegue, publicación ni pruebas sobre la aplicación real.</footer></body></html>'''
